describe("WeightBasedShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects empty brackets array", () => {
      expect(() => new WeightBasedShippingCalculator([])).toThrow(
        "at least one weight bracket is required",
      );
    });

    it("rejects bracket with zero upToGrams", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 0, costCents: 500 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects bracket with negative upToGrams", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: -100, costCents: 500 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects bracket with negative costCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 1000, costCents: -1 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects non-integer overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 1000, costCents: 500 }],
            5.5,
          ),
      ).toThrow(RangeError);
    });

    it("rejects negative overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 1000, costCents: 500 }],
            -1,
          ),
      ).toThrow(RangeError);
    });

    it("accepts valid brackets", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 500, costCents: 300 },
            { upToGrams: 1000, costCents: 600 },
          ]),
      ).not.toThrow();
    });
  });

  describe("computeShippingCents", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 1000, costCents: 500 },
      { upToGrams: 500, costCents: 300 },   // out of order, should be sorted
      { upToGrams: 2000, costCents: 800 },
    ]);

    it("returns 0 for empty cart", () => {
      expect(calc.computeShippingCents([], 5000)).toBe(0);
    });

    it("returns 0 for cart with zero-weight items", () => {
      expect(calc.computeShippingCents([makeLine("a")], 5000)).toBe(0);
    });

    it("selects first bracket when weight is within smallest bracket", () => {
      // 300g → bracket upToGrams=500, cost=300
      expect(
        calc.computeShippingCents([makeLine("a", 300)], 5000),
      ).toBe(300);
    });

    it("selects bracket at exact boundary", () => {
      // 500g → bracket upToGrams=500, cost=300
      expect(
        calc.computeShippingCents([makeLine("a", 500)], 5000),
      ).toBe(300);
    });

    it("selects next bracket when weight exceeds boundary", () => {
      // 501g → bracket upToGrams=1000, cost=500
      expect(
        calc.computeShippingCents([makeLine("a", 501)], 5000),
      ).toBe(500);
    });

    it("selects heaviest bracket at its boundary", () => {
      // 2000g → bracket upToGrams=2000, cost=800
      expect(
        calc.computeShippingCents([makeLine("a", 2000)], 5000),
      ).toBe(800);
    });

    it("uses heaviest bracket cost as overflow default", () => {
      // 2001g → over all brackets → default overflow = heaviest bracket cost = 800
      expect(
        calc.computeShippingCents([makeLine("a", 2001)], 5000),
      ).toBe(800);
    });

    it("uses explicit overflowCostCents when provided", () => {
      const calcWithOverflow = new WeightBasedShippingCalculator(
        [
          { upToGrams: 500, costCents: 300 },
          { upToGrams: 1000, costCents: 500 },
        ],
        1500,
      );
      // 1500g → over all brackets → overflow = 1500
      expect(
        calcWithOverflow.computeShippingCents([makeLine("a", 1500)], 5000),
      ).toBe(1500);
    });

    it("sums weight across multiple lines", () => {
      // 2 items of 400g each = 800g → bracket upToGrams=1000, cost=500
      const lines = [makeLine("a", 400, 2)];
      expect(calc.computeShippingCents(lines, 5000)).toBe(500);
    });

    it("sums weight across multiple products", () => {
      // 600g + 600g = 1200g → bracket upToGrams=2000, cost=800
      const lines = [makeLine("a", 600), makeLine("b", 600)];
      expect(calc.computeShippingCents(lines, 5000)).toBe(800);
    });
  });
});

